/// The quaternion of a rotation matrix: the largest of (trace, R11, R22, R33) picks the form, then
/// it is made unit (no sign forced).
/// - r: real[1][3][3] (passed a plain number)
/// - returns q: real[1][4] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn fromdcm(r: [[f64; 3]; 3]) -> [f64; 4] {
    let mut q: [f64; 4] = [0.0; 4];
    let mut tr: f64 = ((r[0][0] + r[1][1]) + r[2][2]);
    let mut idx: i64 = 0;
    let mut best: f64 = tr;
    if (r[0][0] > best) {
        best = r[0][0];
        idx = 1;
    }
    if (r[1][1] > best) {
        best = r[1][1];
        idx = 2;
    }
    if (r[2][2] > best) {
        idx = 3;
    }
    let mut u: [f64; 4] = [0.0; 4];
    if (idx == 0) {
        u = [(r[1][2] - r[2][1]), (r[2][0] - r[0][2]), (r[0][1] - r[1][0]), (1.0 + tr)];
    } else if (idx == 1) {
        u = [((1.0 + (2.0 * r[0][0])) - tr), (r[0][1] + r[1][0]), (r[0][2] + r[2][0]), (r[1][2] - r[2][1])];
    } else if (idx == 2) {
        u = [(r[1][0] + r[0][1]), ((1.0 + (2.0 * r[1][1])) - tr), (r[1][2] + r[2][1]), (r[2][0] - r[0][2])];
    } else {
        u = [(r[2][0] + r[0][2]), (r[2][1] + r[1][2]), ((1.0 + (2.0 * r[2][2])) - tr), (r[0][1] - r[1][0])];
    }
    q = crate::gen::shared::qnorm(u);
    q
}

/// The quaternion of a rotation vector: [sin(|t|/2) t/|t|, cos(|t|/2)]; below 1e-12 rad
/// [t/2, 1] made unit.
/// - th: real[1][3] (passed a plain number)
/// - returns q: real[1][4] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn fromrotvec(th: [f64; 3]) -> [f64; 4] {
    let mut q: [f64; 4] = [0.0; 4];
    let mut a: f64 = rt::norm(th);
    if (a < 1.0e-12) {
        q = crate::gen::shared::qnorm([(th[0] / 2.0), (th[1] / 2.0), (th[2] / 2.0), 1.0]);
    } else {
        q = [((f64::sin((a / 2.0)) * th[0]) / a), ((f64::sin((a / 2.0)) * th[1]) / a), ((f64::sin((a / 2.0)) * th[2]) / a), f64::cos((a / 2.0))];
    }
    q
}

/// Enter a controller state: the dwell timers reset, the integral cleared; the states that skip
/// estimation (detumble, thruster detumble, spin-up, Sun spin) drop the attitude estimate; spin-up
/// starts its spin-sign window.
/// - st: Modes (passed rec)
/// - mode: int (passed a whole number)
/// - returns s: Modes (passed rec)
#[allow(clippy::too_many_arguments)]
pub fn modes_enter(st: Modes, mode: i64) -> Modes {
    let mut s: Modes = Modes::default();
    s = st;
    if (mode == 5) {
        s.sz_sum = 0.0;
        s.sz_n = 0;
        s.sz_t0 = s.t;
    }
    s.mode = mode;
    s.t_mode = s.t;
    s.hold = 0.0;
    s.ho = false;
    s.ho_t = 0.0;
    if ((((mode == 0) || (mode == 7)) || (mode == 5)) || (mode == 6)) {
        s.ad_ok = false;
        s.n_rej = 0;
    }
    s.i_q = [0.0; 3];
    s
}

/// The Hamilton product a b (scalar last).
/// - a: real[1][4] (passed a plain number)
/// - b: real[1][4] (passed a plain number)
