#[allow(clippy::too_many_arguments)]
pub fn qmult(a: [f64; 4], b: [f64; 4]) -> [f64; 4] {
    let mut r: [f64; 4] = [0.0; 4];
    r = [(((a[3] * b[0]) + (b[3] * a[0])) + ((a[1] * b[2]) - (a[2] * b[1]))), (((a[3] * b[1]) + (b[3] * a[1])) + ((a[2] * b[0]) - (a[0] * b[2]))), (((a[3] * b[2]) + (b[3] * a[2])) + ((a[0] * b[1]) - (a[1] * b[0]))), ((a[3] * b[3]) - (((a[0] * b[0]) + (a[1] * b[1])) + (a[2] * b[2])))];
    r
}

/// q made unit; a zero quaternion becomes the identity.
/// - q: real[1][4] (passed a plain number)
/// - returns r: real[1][4] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn qnorm(q: [f64; 4]) -> [f64; 4] {
    let mut r: [f64; 4] = [0.0; 4];
    let mut n: f64 = f64::sqrt(((((q[0] * q[0]) + (q[1] * q[1])) + (q[2] * q[2])) + (q[3] * q[3])));
    if (n < 1.0e-30) {
        r = [0.0, 0.0, 0.0, 1.0];
    } else {
        r = [(q[0] / n), (q[1] / n), (q[2] / n), (q[3] / n)];
    }
    r
}

/// The skew-symmetric matrix of a: skew(a) b = a x b.
/// - a: real[1][3] (passed a plain number)
/// - returns s: real[1][3][3] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn skew(a: [f64; 3]) -> [[f64; 3]; 3] {
    let mut s: [[f64; 3]; 3] = [[0.0; 3]; 3];
    s = [[0.0, (-(a[2])), a[1]], [a[2], 0.0, (-(a[0]))], [(-(a[1])), a[0], 0.0]];
    s
}
